{"implementation":"import math


def solve(case):
    def error(message):
        return {"error": message}

    def is_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)

    if not isinstance(case, dict):
        return error("case must be an object")

    data = case.get("payload", case)
    if not isinstance(data, dict):
        return error("payload must be an object")

    for field in ("nodes", "core_distance", "distances"):
        if field not in data:
            return error("missing required field: " + field)

    nodes = data["nodes"]
    core_input = data["core_distance"]
    distances = data["distances"]

    if not isinstance(nodes, list):
        return error("nodes must be a list")
    if not isinstance(core_input, dict):
        return error("core_distance must be an object")
    if not isinstance(distances, list):
        return error("distances must be a list")

    seen_nodes = set()
    clean_nodes = []
    for node in nodes:
        if not isinstance(node, str):
            return error("node ids must be strings")
        if node in seen_nodes:
            return error("duplicate node id: " + node)
        seen_nodes.add(node)
        clean_nodes.append(node)

    core_distance = {}
    for node in clean_nodes:
        if node not in core_input:
            return error("missing core distance for node: " + node)
        value = core_input[node]
        if not is_number(value):
            return error("core distance must be a finite number for node: " + node)
        if value < 0:
            return error("core distance must be non-negative for node: " + node)
        core_distance[node] = float(value)

    edge_by_pair = {}
    for index, item in enumerate(distances):
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            return error("distance entry must be a triple at index: " + str(index))
        left, right, distance = item
        if not isinstance(left, str) or not isinstance(right, str):
            return error("distance endpoints must be strings at index: " + str(index))
        if left not in seen_nodes or right not in seen_nodes:
            return error("distance endpoint is not registered at index: " + str(index))
        if left == right:
            return error("self distances are not valid at index: " + str(index))
        if not is_number(distance):
            return error("distance must be a finite number at index: " + str(index))
        if distance < 0:
            return error("distance must be non-negative at index: " + str(index))

        u, v = (left, right) if left <= right else (right, left)
        pair = (u, v)
        if pair in edge_by_pair:
            return error("duplicate undirected distance for pair: " + u + "," + v)
        reachability = max(core_distance[u], core_distance[v], float(distance))
        edge_by_pair[pair] = {
            "left": u,
            "right": v,
            "distance": float(distance),
            "mutual_reachability": reachability,
        }

    mutual_edges = [edge_by_pair[pair] for pair in sorted(edge_by_pair)]
    sorted_edges = sorted(
        mutual_edges,
        key=lambda edge: (edge["mutual_reachability"], edge["left"], edge["right"]),
    )

    parent = {node: node for node in clean_nodes}
    rank = {node: 0 for node in clean_nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            return False
        if rank[root_left] < rank[root_right]:
            parent[root_left] = root_right
        elif rank[root_left] > rank[root_right]:
            parent[root_right] = root_left
        else:
            parent[root_right] = root_left
            rank[root_left] += 1
        return True

    selected = []
    total_weight = 0.0
    needed = max(0, len(clean_nodes) - 1)
    for edge in sorted_edges:
        if union(edge["left"], edge["right"]):
            selected_edge = {
                "left": edge["left"],
                "right": edge["right"],
                "weight": edge["mutual_reachability"],
            }
            selected.append(selected_edge)
            total_weight += edge["mutual_reachability"]
            if len(selected) == needed:
                break

    if len(selected) != needed:
        return error("input graph is disconnected")

    return {
        "core_distance": {node: core_distance[node] for node in clean_nodes},
        "mutual_reachability": mutual_edges,
        "mst_edges": selected,
        "total_weight": total_weight,
    }
"}
